-- +migrate Up
-- Human reference for ledger requests (design G2/G13: the agent copies it
-- as the motif of the mobile-money transfer, ops match the incoming
-- payment against it). Typed prefix + year + sequence, one shared
-- sequence across types: DEP-2026-000042. Generated by add_ledger_request
-- (all writes go through the procedure), never by the caller.
CREATE SEQUENCE ledger_ref_seq;

ALTER TABLE ledger_requests ADD COLUMN ref TEXT;

-- Backfill existing rows with the same shape (year taken from creation).
UPDATE ledger_requests SET ref =
    CASE type
        WHEN 'funding'    THEN 'DEP'
        WHEN 'withdrawal' THEN 'WDR'
        WHEN 'refund'     THEN 'RFD'
        WHEN 'deduction'  THEN 'DED'
        WHEN 'commission' THEN 'COM'
    END || '-' || to_char(created_at, 'YYYY') || '-' ||
    lpad(nextval('ledger_ref_seq')::text, 6, '0');

ALTER TABLE ledger_requests ALTER COLUMN ref SET NOT NULL;
ALTER TABLE ledger_requests ADD CONSTRAINT ledger_requests_ref_uq UNIQUE (ref);

-- +migrate Down
ALTER TABLE ledger_requests DROP CONSTRAINT ledger_requests_ref_uq;
ALTER TABLE ledger_requests DROP COLUMN ref;
DROP SEQUENCE ledger_ref_seq;
